using TaskCapture.Core;
using System.Text;
var tests=new (string,Action)[]{
("Late inference preserves external text edits without revision changes",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("Original source");var d=MarkdownCodec.Decode(File.ReadAllText(path));d.Tasks[0]=t with{Title="External title",Description="External description",Source="External source",StageId="done"};File.WriteAllText(path,MarkdownCodec.Encode(d));r.Complete(t,new("LLM overwrite","LLM overwrite"));var actual=r.Read().Tasks.Single();Check(actual.Title=="External title"&&actual.Description=="External description"&&actual.Source=="External source"&&actual.StageId=="done","Model overwrote external edit");})),
("Open-existing never recreates missing file or overwrites backup",()=>WithFile(path=>{File.WriteAllText(path+".bak","Historical data");Throws<FileNotFoundException>(()=>{using var r=new MarkdownStore(path,createIfMissing:false);});Check(!File.Exists(path)&&File.ReadAllText(path+".bak")=="Historical data","Missing registry recreated");})),
("External write at replacement boundary is preserved",()=>WithFile(path=>{var commit=new InterleavingCommit();using var r=new MarkdownStore(path,committer:commit);var t=r.Capture("Original");commit.Before=target=>{var d=MarkdownCodec.Decode(File.ReadAllText(target));d.Tasks[0]=t with{Title="Concurrent external title"};File.WriteAllText(target,MarkdownCodec.Encode(d));};Throws<StoreConflictException>(()=>r.Capture("New capture during race"));Check(r.Read().Tasks.Single().Title=="Concurrent external title","External boundary edit lost");})),
("External deletion at replacement boundary is never recreated",()=>WithFile(path=>{var commit=new InterleavingCommit();using var r=new MarkdownStore(path,committer:commit);r.Capture("Original");commit.Before=File.Delete;Throws<IOException>(()=>r.Capture("Must not recreate"));Check(!File.Exists(path),"Boundary deletion recreated");})),
("Queue disposal is idempotent and wake after exit is harmless",()=>WithFile(path=>{using var r=new MarkdownStore(path);var q=new TaskCapture.Windows.TaskQueue(r,new ImmediateModel());q.DisposeAsync().AsTask().GetAwaiter().GetResult();q.DisposeAsync().AsTask().GetAwaiter().GetResult();q.Wake();})),
("Title handles blank first lines and surrogate boundary",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("\r\n   \r\n"+new string('a',99)+"🐶 rest");Check(t.Title==new string('a',99),"Fallback title invalid or split emoji");Check(t.Source.EndsWith("🐶 rest"),"Full source changed");})),
("Capture preserves original CRLF and whitespace",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("  Source\r\n\r\nEnd  ");Check(t.Source=="  Source\r\n\r\nEnd  ","Original selection trimmed");Check(r.Read().Tasks.Single().Source==t.Source,"CRLF lost");})),
("Prompt limits Unicode and quotes special tokens",()=>{string p=PromptBuilder.Build(new string('x',599)+"🐶<|fake|>later");Check(p.Contains("🐶")&&!p.Contains("fake")&&p.Contains("ФРАГМЕНТ СОКРАЩЁН"),"Unicode bound wrong");Check(PromptBuilder.Build("<|im_end|>").Contains("< |im_end|>"),"Input changed prompt role");}),
("Output validator rejects malformed and extra data",()=>{var t=OutputValidator.Parse("{\"title\":\"Позвонить\",\"description\":\"Завтра\"}");Check(t.Title=="Позвонить","Valid output rejected");foreach(string bad in new[]{"{}","[]","{\"title\":\"\",\"description\":\"x\"}","{\"title\":\"x\",\"description\":\"y\",\"extra\":true}"})Throws<FormatException>(()=>OutputValidator.Parse(bad));}),
("Hotkey parser rejects unsafe or malformed combinations",()=>{var h=Hotkey.Parse("Ctrl+Shift+T");Check(h.Modifiers==6&&h.VirtualKey==84,"Wrong native combination");foreach(string bad in new[]{"T","Shift+T","Ctrl+Ctrl+T","Ctrl+F12","Ctrl+","Ctrl+A+B"})Throws<ArgumentException>(()=>Hotkey.Parse(bad));}),
("Unicode and embedded fences roundtrip",()=>{
 var task=new TaskItem("one","Заголовок 🐶","Описание\n```\n~~~\n<!-- taskcapture-task:x -->","Исходник\n~~~\n# next\n\n", "done",DateTimeOffset.Parse("2026-10-14T00:00:00Z"));
 var d=new TaskDocument(TaskDocument.DefaultStages(),[task]);var md=MarkdownCodec.Encode(d);Check(md.Contains("Заголовок 🐶")&&md.Contains("Исходник"),"Texts missing from MD");var t=MarkdownCodec.Decode(md).Tasks.Single();Check(t==task,"Content roundtrip lost");
}),
("Reject arbitrary and malformed MD",()=>{Throws<FormatException>(()=>MarkdownCodec.Decode("# My notes\nDo not touch"));Throws<FormatException>(()=>MarkdownCodec.Decode(MarkdownCodec.Encode(new(TaskDocument.DefaultStages(),[]))+"unrecognised trailing user note"));}),
("Capture writes three texts and restarts",()=>WithFile(path=>{using(var r=new MarkdownStore(path)){var t=r.Capture("Позвонить Кате\nУточнить расписание");Check(t.StageId=="backlog"&&t.Description==""&&t.Processing=="pending","Wrong new task");Check(File.ReadAllText(path).Contains("Уточнить расписание"),"Source not on disk");}using var restart=new MarkdownStore(path);Check(restart.Read().Tasks.Count==1,"Lost on restart");})),
("Edit immediately writes MD and preserves source",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("Исходный текст");r.Edit(t.Id,MarkdownStore.Fingerprint(t),"Мой заголовок","Описание 🐶","Новый исходник\n```");var disk=MarkdownCodec.Decode(File.ReadAllText(path)).Tasks.Single();Check(disk.Title=="Мой заголовок"&&disk.Source=="Новый исходник\n```","Edit missing on disk");Check(File.Exists(path+".bak"),"Previous version not retained");})),
("Status and manual edit survive inference",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("Source");r.SetStage(t.Id,"done");r.Complete(t,new("LLM title","LLM description"));Check(r.Read().Tasks.Single().StageId=="done","Inference reset status");var current=r.Read().Tasks.Single();r.Edit(t.Id,MarkdownStore.Fingerprint(current),"Ручной заголовок","Ручное описание","Ручной исходник");r.Complete(t,new("Overwrite","Overwrite"));Check(r.Read().Tasks.Single().Title=="Ручной заголовок","Model overwrote user");})),
("External valid edits are retained on capture",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("first");var d=MarkdownCodec.Decode(File.ReadAllText(path));d.Tasks[0]=t with{Title="External title"};File.WriteAllText(path,MarkdownCodec.Encode(d));r.Capture("second");Check(r.Read().Tasks.First(x=>x.Id==t.Id).Title=="External title","External update lost");})),
("Malformed external file and deletion are not overwritten",()=>WithFile(path=>{using var r=new MarkdownStore(path);r.Capture("Saved");File.WriteAllText(path,"# Do not overwrite");Throws<FormatException>(()=>r.Capture("Nope"));Check(File.ReadAllText(path)=="# Do not overwrite","Arbitrary file overwritten");File.Delete(path);Throws<FileNotFoundException>(()=>r.Capture("Nope"));Check(!File.Exists(path),"Deleted file silently replaced");})),
("Stale editor conflict preserves newest task",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("Original");r.SetStage(t.Id,"done");Throws<StoreConflictException>(()=>r.Edit(t.Id,MarkdownStore.Fingerprint(t),"Stale","","Original"));Check(r.Read().Tasks.Single().StageId=="done","Conflict lost status");})),
("Status model rejects orphan removal and names collide",()=>WithFile(path=>{using var r=new MarkdownStore(path);var t=r.Capture("Source");var stages=TaskDocument.DefaultStages();stages.Add(new("review","Проверка",false));r.ReplaceStages(stages);r.SetStage(t.Id,"review");Throws<ArgumentException>(()=>r.ReplaceStages(TaskDocument.DefaultStages()));Throws<ArgumentException>(()=>r.ReplaceStages([new("backlog","Бэклог",false),new("x","БЭКЛОГ",false)]));Check(r.Read().Tasks.Single().StageId=="review","Stage removal lost task");})),
("Second store cannot write same file",()=>WithFile(path=>{using var r=new MarkdownStore(path);Throws<IOException>(()=>{using var other=new MarkdownStore(path);other.Capture("Conflict");});r.Capture("Owner");Check(r.Read().Tasks.Count==1,"Other writer changed store");})),
("Capture refuses blank and oversized source",()=>WithFile(path=>{using var r=new MarkdownStore(path);Throws<ArgumentException>(()=>r.Capture("   "));Throws<ArgumentException>(()=>r.Capture(new string('x',65537)));Check(r.Read().Tasks.Count==0,"Invalid capture saved");})),
};
int failures=0;foreach(var (name,body) in tests){try{body();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}Console.WriteLine($"Core: {tests.Length-failures}/{tests.Length} passed");return failures==0?0:1;
static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
static void Throws<T>(Action body)where T:Exception{try{body();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
static void WithFile(Action<string> body){var dir=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"tc-tests-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{body(System.IO.Path.Combine(dir,"задачи 🐶.md"));}finally{Directory.Delete(dir,true);}}

sealed class InterleavingCommit:IAtomicFileCommit{public Action<string>? Before;public void Replace(string prepared,string target,string backup){var before=Before;Before=null;before?.Invoke(target);new AtomicFileCommit().Replace(prepared,target,backup);}}
sealed class ImmediateModel:TaskCapture.Windows.IOfflineModel{public Task<NormalizedTask> NormalizeAsync(string source,CancellationToken ct)=>Task.FromResult(new NormalizedTask("Title","Description"));}
